def curvature_endpoint_api_source(original):
    assert type(CURVATURE_ENDPOINT_API_EDITS) is tuple
    assert len(CURVATURE_ENDPOINT_API_EDITS)==20
    assert all(type(row) is tuple and len(row)==2 and all(type(v) is str for v in row)
               for row in CURVATURE_ENDPOINT_API_EDITS)
    serial=json.dumps(CURVATURE_ENDPOINT_API_EDITS,ensure_ascii=False,separators=(',',':')).encode()
    assert sha256(serial)=='53ad96e032a8032f557c2c0e9934b883c424917396b6ac30fb5babdedeaa7f15', 'Exact finite endpoint API/proof policy drift'
    assert sha256(original)=='474af52d61a6a90197d92ee24517952863cc834b66c3158c98182e78de21771f', 'Original endpoint source drift'
    changed=original.decode('utf8')
    for before,after in CURVATURE_ENDPOINT_API_EDITS:
        assert changed.count(before)==1, 'Missing/duplicate endpoint original transform'
        changed=changed.replace(before,after,1)
    recovered=changed
    for before,after in reversed(CURVATURE_ENDPOINT_API_EDITS):
        assert recovered.count(after)==1, 'Missing/duplicate endpoint current transform'
        recovered=recovered.replace(after,before,1)
    assert recovered.encode()==original, 'Complete endpoint original source recovery drift'
    assert sha256(changed.encode())=='c887086ba419713560be58da93872c5d1bdc1ac07e8bd1e6a1c90ecc460a7f9a', 'Exact endpoint current source drift'
    assert sha256(json.dumps(CURVATURE_ENDPOINT_API_EDITS,ensure_ascii=False,separators=(',',':')).encode())=='53ad96e032a8032f557c2c0e9934b883c424917396b6ac30fb5babdedeaa7f15'
    return changed.encode()

def curvature_scalar_audit_workflow_source(original):
    assert sha256(original)=='e4f39177d37c5edba8815c97c5d348f4341fe6db9363484f20b326db1978ae74', 'Original scalar workflow provenance drift'
    before=b'          bash scripts/point4_audit.sh --json /tmp/point4-manifold-heat-full-audit.json | tee /tmp/point4-manifold-heat-full-audit.log\n'
    after=b'          PYTHONDONTWRITEBYTECODE=1 bash scripts/point4_audit.sh --json /tmp/point4-manifold-heat-full-audit.json | tee /tmp/point4-manifold-heat-full-audit.log\n'
    assert original.count(before)==1 and after not in original, 'Scalar audit invocation missing/duplicate'
    current=original.replace(before,after,1)
    assert current.count(after)==1 and current.replace(after,before,1)==original, 'Whole scalar workflow inverse drift'
    assert sha256(current)=='2a359ac08705e13d41054eb472fad1980f4ec08e3ff6b9a946de82c23d1de0fb', 'Exact scalar workflow current source drift'
    return current

def curvature_hamilton_current_source(path,original):
    assert type(CURVATURE_HAMILTON_SOURCE_EDITS) is dict and set(CURVATURE_HAMILTON_SOURCE_EDITS)==set(CURVATURE_HAMILTON_ORIGINAL_SHA256)==set(CURVATURE_HAMILTON_SOURCE_SHA256)
    assert CURVATURE_HAMILTON_ORIGINAL_SHA256=={'scripts/point4/audit-hamilton-release.py': '1380a57af471e0c6b062ab3e381f4c4cae095dfdf4bf1250f16a3fc677c2245e', 'scripts/point4/test_audit_hamilton_release.py': 'c7cb8aff1fc8277954c36301e6fa2e2e63b50958e2cb163d8dd9d361ae8ddddd', 'scripts/point4/build-hamilton-batches.lean': '602e3207830355f3f23caf5c2a79ce57fc03442d7cfc245897ae5d179eb3c432', '.github/workflows/point4-hamilton-release-audit.yml': '078fe0190561d9304f26c81268c085e716ee86bd0a362676e1796dc58d03243f'} and CURVATURE_HAMILTON_SOURCE_SHA256=={'scripts/point4/audit-hamilton-release.py': 'bb5aab5e6a24fe5fd390a64d1ef363298dc76858dd7ad73a53c70b735bfeffe6', 'scripts/point4/test_audit_hamilton_release.py': 'a4bbbbd2e033279709e7f090a0177eb505ccbd3bf6b5ac88fd3fdf9bbb595ef1', 'scripts/point4/build-hamilton-batches.lean': '4df8942448ba7ad6d5152fb0bcc6e81684cac9241c36e39de0140e60638eb2a7', '.github/workflows/point4-hamilton-release-audit.yml': '1d8849f98be74899334bedc94ed68c46b1270c420e9454f66a27d28e791d4c2d'}, 'Fixed Hamilton source hashes drift'
    serial=json.dumps(CURVATURE_HAMILTON_SOURCE_EDITS,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()
    assert sha256(serial)==CURVATURE_HAMILTON_POLICY_SHA256=='11e7ad4195f7affd59297e253abfab9057845ca8e05f6e496b11aaa5ca92b2e6', 'Finite Hamilton source policy drift'
    assert path in CURVATURE_HAMILTON_SOURCE_EDITS and sha256(original)==CURVATURE_HAMILTON_ORIGINAL_SHA256[path], 'Original Hamilton source provenance drift'
    edits=CURVATURE_HAMILTON_SOURCE_EDITS[path]
    assert type(edits) is tuple and len(edits)=={'scripts/point4/audit-hamilton-release.py': 4, 'scripts/point4/test_audit_hamilton_release.py': 3, 'scripts/point4/build-hamilton-batches.lean': 1, '.github/workflows/point4-hamilton-release-audit.yml': 1}[path]
    changed=original.decode('utf8')
    for before,after in edits:
        assert type(before) is str and type(after) is str and before!=after
        assert changed.count(before)==1 and after not in changed, 'Missing/duplicate Hamilton original transform'
        changed=changed.replace(before,after,1)
    recovered=changed
    for before,after in reversed(edits):
        assert recovered.count(after)==1, 'Missing/duplicate Hamilton current inverse'
        recovered=recovered.replace(after,before,1)
    assert recovered.encode()==original, 'Complete original Hamilton source recovery drift'
    assert sha256(changed.encode())==CURVATURE_HAMILTON_SOURCE_SHA256[path], 'Exact Hamilton current source drift'
    assert sha256(json.dumps(CURVATURE_HAMILTON_SOURCE_EDITS,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode())==CURVATURE_HAMILTON_POLICY_SHA256=='11e7ad4195f7affd59297e253abfab9057845ca8e05f6e496b11aaa5ca92b2e6'
    return changed.encode()


