    complete=dict(base)
    for path,row in sealed.items():
        assert set(row)=={'mode','sha256','blob','origin'} and row['mode']=='100644'
        file=ROOT/path
        for parent in file.parents:
            assert stat.S_ISDIR(parent.lstat().st_mode) and not parent.is_symlink()
            if parent==ROOT:break
        assert stat.S_ISREG(file.lstat().st_mode) and not file.is_symlink()
        data=file.read_bytes();assert sha256(data)==row['sha256'] and blob_id(data)==row['blob'], 'Exact qualified resolvent Source drift: '+path
        complete[path]=('100644',row['blob'])
