CURVATURE_CHART_LIFECYCLE_PREVIOUS_HELPER_SHA256='194a4a8804a5d00f5346c09a0bf759d2532dffb32b988932eca6fc43400a647c'
CURVATURE_CHART_LIFECYCLE_HELPER_PORTS=(("    assert type(raw) is bytes and sha256(raw)==CURVATURE_GIT_BATCH_RUNTIME_HELPER_SHA256, 'Complete current catalog correction Source drift'\n", "    assert type(raw) is bytes and sha256(raw)==CURVATURE_CHART_LIFECYCLE_PREVIOUS_HELPER_SHA256, 'Exact preceding catalog helper Source drift'\n"), ('    raw=curvature_resolvent_current_catalog_helper_inverse(raw)\r\n', '    raw=curvature_chart_lifecycle_helper_inverse(raw)\r\n    raw=curvature_resolvent_current_catalog_helper_inverse(raw)\r\n'))

def curvature_chart_lifecycle_policy_check():
    assert type(CURVATURE_CHART_LIFECYCLE_SOURCES) is dict and set(CURVATURE_CHART_LIFECYCLE_SOURCES)=={'curvature/scripts/chart_port_ci.py','curvature/scripts/test_chart_port_ci.py'}, 'Exact chart lifecycle Source surfaces drift'
    assert sha256(json.dumps(CURVATURE_CHART_LIFECYCLE_SOURCES,sort_keys=True,separators=(',',':')).encode())==CURVATURE_CHART_LIFECYCLE_POLICY_SHA256=='335ec4178cdd0a470303c7b5f5ee7a7b09ca164a92dfd80ac3571dac81f27190', 'Chart lifecycle Source/provenance policy mutation'

def curvature_chart_lifecycle_source_inverse(path,raw):
    curvature_chart_lifecycle_policy_check()
    row=CURVATURE_CHART_LIFECYCLE_SOURCES[path]
    assert type(raw) is bytes and sha256(raw)==row['after_sha256'], 'Whole current chart lifecycle Source drift: '+path
    text=raw.decode('utf8')
    for before,after in reversed(row['ports']):
        assert text.count(after)==1, 'Missing/duplicate chart lifecycle inverse port'
        text=text.replace(after,before,1)
    restored=text.encode('utf8')
    assert sha256(restored)==row['before_sha256'], 'Whole original chart Source not recovered: '+path
    for before,after in row['ports']:
        assert text.count(before)==1 and after not in text, 'Original chart lifecycle forward port drift'
        text=text.replace(before,after,1)
    assert text.encode('utf8')==raw, 'Whole current chart lifecycle forward recovery drift'
    curvature_chart_lifecycle_policy_check()
    return restored

def curvature_chart_lifecycle_source(path,original):
    curvature_chart_lifecycle_policy_check()
    row=CURVATURE_CHART_LIFECYCLE_SOURCES[path]
    assert type(original) is bytes and sha256(original)==row['before_sha256'], 'Exact previous chart Source drift: '+path
    text=original.decode('utf8')
    for before,after in row['ports']:
        assert text.count(before)==1 and after not in text, 'Missing/duplicate chart lifecycle forward port'
        text=text.replace(before,after,1)
    changed=text.encode('utf8')
    assert sha256(changed)==row['after_sha256'] and curvature_chart_lifecycle_source_inverse(path,changed)==original, 'Whole chart lifecycle Source inverse drift'
    return changed

_curvature_before_terminal_lifecycle_selected_source=curvature_selected_source
def curvature_selected_source(path,digest=None):
    # All historical constructors and original byte checks run before this
    # finite actual-current transform. Historical helper views retain old bytes.
    original=_curvature_before_terminal_lifecycle_selected_source(path,digest)
    current=sha256((ROOT/HELPER).read_bytes())
    if path in CURVATURE_CHART_LIFECYCLE_SOURCES and (digest is None or digest==current):
        return curvature_chart_lifecycle_source(path,original)
    return original

def curvature_chart_lifecycle_helper_inverse(raw):
    assert type(raw) is bytes and sha256(raw)==CURVATURE_CHART_CACHE_PHASE_SPLIT_PREVIOUS_HELPER_SHA256, 'Exact preceding lifecycle helper Source drift'
    assert sha256((ROOT/HELPER).read_bytes())==CURVATURE_GIT_BATCH_RUNTIME_HELPER_SHA256, 'Combined current helper input mutation'
    text=raw.decode('utf8')
    start='# BEGIN exact owned chart terminal lifecycle correction\n'
    end='# END exact owned chart terminal lifecycle correction\n\n'
    assert text.count(start)==text.count(end)==1, 'Exact chart helper inverse boundary drift'
    first=text.index(start);last=text.index(end,first)+len(end)
    text=text[:first]+text[last:]
    for before,after in reversed(CURVATURE_CHART_LIFECYCLE_HELPER_PORTS):
        assert text.count(after)==1, 'Missing/duplicate combined helper inverse port'
        text=text.replace(after,before,1)
    restored=text.encode('utf8')
    assert sha256(restored)==CURVATURE_CHART_LIFECYCLE_PREVIOUS_HELPER_SHA256, 'Whole reviewed catalogv2 helper not recovered'
    return restored
# END exact owned chart terminal lifecycle correction

