def curvature_chart_cache_phase_split_policy_check():
    assert type(CURVATURE_CHART_CACHE_PHASE_SPLIT_SOURCES) is dict and set(CURVATURE_CHART_CACHE_PHASE_SPLIT_SOURCES)==set(('curvature/scripts/chart_port_ci.py', 'curvature/scripts/test_chart_port_ci.py')), 'Exact chart phase split path policy drift'
    assert sha256(json.dumps(CURVATURE_CHART_CACHE_PHASE_SPLIT_SOURCES,sort_keys=True,separators=(',',':')).encode())==CURVATURE_CHART_CACHE_PHASE_SPLIT_POLICY_SHA256=='905d5a1fece457172b35979cd3a7a850035fc91b5e20c7cea8f428021c40e872', 'Chart phase split Source/provenance mutation'

def curvature_chart_cache_phase_split_source_inverse(path,raw):
    curvature_chart_cache_phase_split_policy_check()
    row=CURVATURE_CHART_CACHE_PHASE_SPLIT_SOURCES[path]
    assert type(raw) is bytes and sha256(raw)==row['after_sha256'], 'Whole current phase split Source drift: '+path
    text=raw.decode('utf8')
    for before,after in reversed(row['ports']):
        assert text.count(after)==1, 'Missing/duplicate phase split inverse port'
        text=text.replace(after,before,1)
    restored=text.encode('utf8')
    assert sha256(restored)==row['before_sha256'], 'Whole previous chart Source not recovered: '+path
    for before,after in row['ports']:
        assert text.count(before)==1, 'Missing/duplicate phase split forward port'
        text=text.replace(before,after,1)
    assert text.encode('utf8')==raw, 'Whole chart phase split forward recovery drift'
    curvature_chart_cache_phase_split_policy_check()
    return restored

def curvature_chart_cache_phase_split_source(path,original):
    curvature_chart_cache_phase_split_policy_check()
    row=CURVATURE_CHART_CACHE_PHASE_SPLIT_SOURCES[path]
    assert type(original) is bytes and sha256(original)==row['before_sha256'], 'Exact previous chart Source drift: '+path
    text=original.decode('utf8')
    for before,after in row['ports']:
        assert text.count(before)==1, 'Missing/duplicate phase split forward Source port'
        text=text.replace(before,after,1)
    changed=text.encode('utf8')
    assert sha256(changed)==row['after_sha256'] and curvature_chart_cache_phase_split_source_inverse(path,changed)==original, 'Whole chart phase split inverse drift'
    return changed

_curvature_before_cache_phase_split_selected_source=curvature_selected_source
def curvature_selected_source(path,digest=None):
    original=_curvature_before_cache_phase_split_selected_source(path,digest)
    current=sha256((ROOT/HELPER).read_bytes())
    if path in CURVATURE_CHART_CACHE_PHASE_SPLIT_SOURCES and (digest is None or digest==current):
        return curvature_chart_cache_phase_split_source(path,original)
    return original

def curvature_chart_cache_phase_split_helper_inverse(raw):
    assert type(raw) is bytes and sha256(raw)==CURVATURE_CHART_CACHE_JSON_PREVIOUS_HELPER_SHA256, 'Exact preceding phase split helper Source drift'
    assert sha256((ROOT/HELPER).read_bytes())==CURVATURE_GIT_BATCH_RUNTIME_HELPER_SHA256, 'Chart phase split helper input mutation'
    text=raw.decode('utf8')
    start='# BEGIN exact chart cache manifest acquisition phase split\n'
    end='# END exact chart cache manifest acquisition phase split\n\n'
    assert text.count(start)==text.count(end)==1, 'Exact chart phase split inverse boundary drift'
    first=text.index(start);last=text.index(end,first)+len(end)
    text=text[:first]+text[last:]
    for before,after in reversed(CURVATURE_CHART_CACHE_PHASE_SPLIT_HELPER_PORTS):
        assert text.count(after)==1, 'Missing/duplicate chart phase split helper inverse port'
        text=text.replace(after,before,1)
    restored=text.encode('utf8')
    assert sha256(restored)==CURVATURE_CHART_CACHE_PHASE_SPLIT_PREVIOUS_HELPER_SHA256, 'Whole reviewed08ce helper0ec not recovered'
    return restored

