def curvature_chart_cache_json_policy_check():
    assert type(CURVATURE_CHART_CACHE_JSON_SOURCES) is dict and set(CURVATURE_CHART_CACHE_JSON_SOURCES)==set(('curvature/scripts/chart_port_ci.py', 'curvature/scripts/test_chart_port_ci.py')), 'Exact chart JSON contract path policy drift'
    assert sha256(json.dumps(CURVATURE_CHART_CACHE_JSON_SOURCES,sort_keys=True,separators=(',',':')).encode())==CURVATURE_CHART_CACHE_JSON_POLICY_SHA256=='f1e7edea448ae1b52d0f4f6dea8663f6a4ad27ba654cce5599542bf37462bc5d', 'Chart JSON contract Source/provenance mutation'

def curvature_chart_cache_json_source_inverse(path,raw):
    curvature_chart_cache_json_policy_check()
    row=CURVATURE_CHART_CACHE_JSON_SOURCES[path]
    assert type(raw) is bytes and sha256(raw)==row['after_sha256'], 'Whole chart JSON Source drift: '+path
    text=raw.decode('utf8')
    for before,after in reversed(row['ports']):
        assert text.count(after)==1, 'Missing/duplicate chart JSON inverse port'
        text=text.replace(after,before,1)
    restored=text.encode('utf8')
    assert sha256(restored)==row['before_sha256'], 'Whole preceding chart Source not recovered: '+path
    for before,after in row['ports']:
        assert text.count(before)==1, 'Missing/duplicate chart JSON forward port'
        text=text.replace(before,after,1)
    assert text.encode('utf8')==raw, 'Whole chart JSON forward recovery drift'
    curvature_chart_cache_json_policy_check()
    return restored

def curvature_chart_cache_json_source(path,original):
    curvature_chart_cache_json_policy_check()
    row=CURVATURE_CHART_CACHE_JSON_SOURCES[path]
    assert type(original) is bytes and sha256(original)==row['before_sha256'], 'Exact preceding chart Source drift: '+path
    text=original.decode('utf8')
    for before,after in row['ports']:
        assert text.count(before)==1, 'Missing/duplicate chart JSON Source port'
        text=text.replace(before,after,1)
    changed=text.encode('utf8')
    assert sha256(changed)==row['after_sha256'] and curvature_chart_cache_json_source_inverse(path,changed)==original, 'Whole chart JSON inverse drift'
    return changed

_curvature_before_cache_json_selected_source=curvature_selected_source
def curvature_selected_source(path,digest=None):
    original=_curvature_before_cache_json_selected_source(path,digest)
    current=sha256((ROOT/HELPER).read_bytes())
    if path in CURVATURE_CHART_CACHE_JSON_SOURCES and (digest is None or digest==current):
        return curvature_chart_cache_json_source(path,original)
    return original

def curvature_chart_cache_json_helper_inverse(raw):
    assert type(raw) is bytes and sha256(raw)==CURVATURE_CHART_TERMINAL_OWNER_PREVIOUS_HELPER_SHA256, 'Exact preceding JSON helper Source drift'
    assert sha256((ROOT/HELPER).read_bytes())==CURVATURE_GIT_BATCH_RUNTIME_HELPER_SHA256, 'Chart JSON helper input mutation'
    text=raw.decode('utf8')
    start='# BEGIN exact chart cache numeric generation JSON contract\n'
    end='# END exact chart cache numeric generation JSON contract\n\n'
    assert text.count(start)==text.count(end)==1, 'Exact chart JSON inverse boundary drift'
    first=text.index(start);last=text.index(end,first)+len(end)
    text=text[:first]+text[last:]
    for before,after in reversed(CURVATURE_CHART_CACHE_JSON_HELPER_PORTS):
        assert text.count(after)==1, 'Missing/duplicate chart JSON helper inverse port'
        text=text.replace(after,before,1)
    restored=text.encode('utf8')
    assert sha256(restored)==CURVATURE_CHART_CACHE_JSON_PREVIOUS_HELPER_SHA256, 'Whole d432 helper aeca not recovered'
    return restored

_curvature_before_cache_json_map=tensor_map_record
def tensor_map_record(expected,originals,changes):
    record=_curvature_before_cache_json_map(expected,originals,changes)
    record['curvature_finite_input_preparation']['chart_cache_numeric_generation_JSON_contract']=CURVATURE_CHART_CACHE_JSON_RECORD
    return record
