def curvature_chart_terminal_owner_source_inverse(path,raw):
    curvature_chart_terminal_owner_policy_check()
    row=CURVATURE_CHART_TERMINAL_OWNER_SOURCES[path]
    assert type(raw) is bytes and sha256(raw)==row['after_sha256'], 'Whole terminal owner chart Source drift: '+path
    text=raw.decode('utf8')
    for before,after in reversed(row['ports']):
        assert text.count(after)==1, 'Missing/duplicate terminal owner inverse port'
        text=text.replace(after,before,1)
    restored=text.encode('utf8')
    assert sha256(restored)==row['before_sha256'], 'Whole preceding chart Source not recovered: '+path
    for before,after in row['ports']:
        assert text.count(before)==1, 'Missing/duplicate terminal owner forward port'
        text=text.replace(before,after,1)
    assert text.encode('utf8')==raw, 'Whole terminal owner forward recovery drift'
    curvature_chart_terminal_owner_policy_check()
    return restored

