def curvature_weighted_builtin_routing_policy_check():
    assert type(CURVATURE_WEIGHTED_BUILTIN_ROUTING_POLICY) is dict
    assert sha256(json.dumps(CURVATURE_WEIGHTED_BUILTIN_ROUTING_POLICY,sort_keys=True,separators=(',',':')).encode())==CURVATURE_WEIGHTED_BUILTIN_ROUTING_SHA256=='e703b878a0e004567851e30b0dd6c6bc470b52815588bfa6f5ccea3252c0ebeb', 'Builtin routing policy drift'

def curvature_weighted_builtin_helper_inverse(raw):
    curvature_weighted_builtin_routing_policy_check()
    assert type(raw) is bytes and sha256(raw)==CURVATURE_GIT_BATCH_RUNTIME_HELPER_SHA256, 'Whole builtin repair helper drift'
    assert sha256((ROOT/HELPER).read_bytes())==CURVATURE_GIT_BATCH_RUNTIME_HELPER_SHA256, 'Builtin helper input mutation'
    start=b'# BEGIN exact weighted builtin namespace authority routing\n'
    end=b'# END exact weighted builtin namespace authority routing\n'
    assert raw.count(start)==raw.count(end)==1 and raw.endswith(end), 'Builtin routing boundary drift'
    prefix=raw[:raw.index(start)];assert prefix.endswith(b'\n\n');prefix=prefix[:-2]
    marker=b'# BEGIN exact weighted immutable inventory routing\n'
    assert prefix.count(marker)==1
    core,append=prefix.split(marker,1);assert core.endswith(b'\n\n');core=core[:-2]
    append=marker+append;policy=CURVATURE_WEIGHTED_BUILTIN_ROUTING_POLICY
    assert sha256(core)==policy['current_core_sha256'], 'Whole builtin core Source drift'
    text=core.decode('utf8')
    for before,after in reversed(policy['helper_ports']):
        assert text.count(after)==1, 'Builtin helper inverse port drift';text=text.replace(after,before,1)
    old_core=text.encode('utf8');assert sha256(old_core)==policy['previous_core_sha256'], 'Whole ac0d core not recovered'
    before,after=policy['seam'];text=append.decode('utf8')
    assert text.count(after)==1, 'Builtin old helper seam drift';text=text.replace(after,before,1)
    restored=old_core+b'\n\n'+text.encode('utf8')
    assert sha256(restored)==policy['previous_helper_sha256'], 'Whole a21 predecessor helper not recovered'
    assert sha256((ROOT/HELPER).read_bytes())==CURVATURE_GIT_BATCH_RUNTIME_HELPER_SHA256, 'Builtin helper POST mutation'
    curvature_weighted_builtin_routing_policy_check();return restored

